import math

def can_obtain_sequence(N, B):
    for i in range(N):
        if B[i] != i + 1:
            g = B[i]
            for j in range(i, N):
                g = math.gcd(g, B[j])
                if g == 1:
                    break
                if B[j] % g == 0:
                    B[j] //= g
